ruleSearch.bookList:
@js:var out = [];
try {
  // 书号为 19 位时按数字返回会被 JS 截断，先把裸数字包成字符串再解析
  var raw = String(result)
    .replace(/"book_id"\s*:\s*(\d{15,})/g, '"book_id":"$1"')
    .replace(/"bookId"\s*:\s*(\d{15,})/g, '"bookId":"$1"');
  var j = JSON.parse(raw);
  var d = (j && j.data) || {};
  var rs = d.resp_data || {};
  var sb = rs.search_book_data || {};
  var list = sb.book_data || sb.bookData || [];
  for (var i = 0; i < list.length; i++) {
    var b = list[i] || {};
    var id = String(b.book_id || b.bookId || '');
    if (!id) continue;
    out.push({
      book_id: id,
      book_name: b.book_name || b.bookName || '',
      author: b.author || b.author_name || b.authorName || '',
      abstract: b.abstract || b.intro || '',
      thumb_url: b.thumb_url || b.thumbUrl || b.expand_thumb_url || '',
      word_number: b.word_number || b.wordNumber || '',
      category: b.category || b.category_name || '',
      last_chapter_title: b.last_chapter_title || b.lastChapterTitle || ''
    });
  }
} catch (e) {}
JSON.stringify(out);

