'https://fanqienovel.com/page/' + id;

ruleToc.chapterList:
@js:var out = [];
try {
  var bid = String(baseUrl).replace(/[^0-9]/g, '');
  var txt = java.ajax('https://fanqienovel.com/api/reader/directory/detail?bookId=' + bid);
  txt = String(txt).replace(/"itemId"\s*:\s*(\d{15,})/g, '"itemId":"$1"');
  var j = JSON.parse(txt);
  var vols = (j.data && j.data.chapterListWithVolume) || [];
  for (var v = 0; v < vols.length; v++) {
    var chs = vols[v] || [];
    for (var i = 0; i < chs.length; i++) {
      var c = chs[i] || {};
      if (!c.itemId) continue;
      out.push({
        title: String(c.title || ('第' + (out.length + 1) + '章')),
        url: 'https://fanqienovel.com/api/reader/full?itemId=' + c.itemId,
        isVip: c.isChapterLock === true
      });
    }
  }
} catch (e) {}
JSON.stringify(out);

